def remove(self) -> None:
    try:
        os.rmdir(self.path)
    except FileNotFoundError:
        pass
    try:
        os.rmdir(self.parent_path)
    except OSError as e:
        if e.errno not in (errno.EBUSY, errno.ENOTEMPTY, errno.ENOENT):
            raise

